// A tiny stand-in for what JSX compiles to.
function h(type, props, ...children) {
  return { type, props: { ...props, children } };
}

// Write the h() calls this JSX compiles to:
//
// <article className="card">
//   <h2>{movie.title}</h2>
//   <p>{movie.year}</p>
// </article>
function buildCard(movie) {
  return h('article', { className: 'card' },
    h('h2', null, movie.title),
    h('p', null, movie.year),
  );
}
